<?php
$content = file_get_contents('api.php');
$target = "    \$hashed = password_hash(\$new_password, PASSWORD_BCRYPT, ['cost' => 10]);\n    \$stmtUpgrade = \$db->prepare('UPDATE users SET password = ? WHERE id = ?');\n    \$stmtUpgrade->execute([\$hashed, \$user['id']]);\n\n    echo json_encode(['success' => true]);\n    exit;\n}\n\n// 6. Siswa Endpoints";

$replacement = "    \$hashed = password_hash(\$new_password, PASSWORD_BCRYPT, ['cost' => 10]);\n    \$stmtUpgrade = \$db->prepare('UPDATE users SET password = ? WHERE id = ?');\n    \$stmtUpgrade->execute([\$hashed, \$user['id']]);\n\n    echo json_encode(['success' => true]);\n    exit;\n}\n\n// 5.6 Request OTP Endpoint\nif (\$uri === '/api/request-otp' && \$method === 'POST') {\n    \$username = \$inputBody['username'] ?? '';\n    if (!\$username) {\n        http_response_code(400); echo json_encode(['error' => 'Username diperlukan']); exit;\n    }\n    \n    \$sanitizedUsername = preg_replace('/[^a-zA-Z0-9_@.]/', '', \$username);\n    \$stmt = \$db->prepare('SELECT id, email, username FROM users WHERE username = ?');\n    \$stmt->execute([\$sanitizedUsername]);\n    \$user = \$stmt->fetch();\n\n    if (!\$user) {\n        http_response_code(404); echo json_encode(['error' => 'Akun tidak ditemukan']); exit;\n    }\n\n    \$email = \$user['email'];\n    if (!\$email) {\n        http_response_code(400); echo json_encode(['error' => 'Akun ini belum memiliki email terdaftar. Hubungi Owner/Developer untuk menyetel email Anda.']); exit;\n    }\n\n    \$otp = sprintf('%06d', mt_rand(1, 999999));\n    \$expires = time() + (15 * 60);\n\n    \$db->prepare('UPDATE users SET otp_code = ?, otp_expires = ? WHERE id = ?')->execute([\$otp, \$expires, \$user['id']]);\n\n    \$subject = 'Kode OTP Reset Password WLC';\n    \$message = 'Kode OTP Anda adalah: ' . \$otp . \"\\n\\nBerlaku selama 15 menit. Abaikan email ini jika Anda tidak merasa memintanya.\";\n    \$headers = \"From: admin@elyana.biz.id\\r\\nReply-To: admin@elyana.biz.id\\r\\n\";\n\n    @mail(\$email, \$subject, \$message, \$headers);\n\n    echo json_encode(['success' => true, 'message' => 'OTP telah dikirim ke email terdaftar.']);\n    exit;\n}\n\n// 5.7 Reset with OTP Endpoint\nif (\$uri === '/api/reset-with-otp' && \$method === 'POST') {\n    \$username = \$inputBody['username'] ?? '';\n    \$otp = \$inputBody['otp'] ?? '';\n    \$new_password = \$inputBody['new_password'] ?? '';\n\n    if (!\$username || !\$otp || !\$new_password) {\n        http_response_code(400); echo json_encode(['error' => 'Data tidak lengkap']); exit;\n    }\n    if (strlen(\$new_password) < 8) {\n        http_response_code(400); echo json_encode(['error' => 'Password baru minimal 8 karakter']); exit;\n    }\n\n    \$sanitizedUsername = preg_replace('/[^a-zA-Z0-9_@.]/', '', \$username);\n    \$stmt = \$db->prepare('SELECT id, otp_code, otp_expires FROM users WHERE username = ?');\n    \$stmt->execute([\$sanitizedUsername]);\n    \$user = \$stmt->fetch();\n\n    if (!\$user || \$user['otp_code'] !== \$otp) {\n        http_response_code(400); echo json_encode(['error' => 'OTP salah atau akun tidak ditemukan']); exit;\n    }\n    if (time() > \$user['otp_expires']) {\n        http_response_code(400); echo json_encode(['error' => 'OTP sudah kedaluwarsa']); exit;\n    }\n\n    \$hashed = password_hash(\$new_password, PASSWORD_BCRYPT, ['cost' => 10]);\n    \$db->prepare('UPDATE users SET password = ?, otp_code = NULL, otp_expires = NULL WHERE id = ?')->execute([\$hashed, \$user['id']]);\n\n    echo json_encode(['success' => true]);\n    exit;\n}\n\n// 6. Siswa Endpoints";

if (strpos($content, $target) !== false) {
    file_put_contents('api.php', str_replace($target, $replacement, $content));
    echo "Success!";
